import{c as l,Q as o,j as a,m as e}from"./chunks/framework.DOi4mjdC.js";const u="/assets/%E5%86%85%E5%AD%98.CyySS_xv.png",s="/assets/UB%E5%86%85%E5%AD%98%E5%88%86%E9%85%8D.CycysjF4.png",h=JSON.parse('{"title":"内存层级","description":"","frontmatter":{},"headers":[{"level":1,"title":"内存层级","slug":"内存层级"},{"level":2,"title":"全局内存（Global Memory）","slug":"全局内存global-memory"},{"level":2,"title":"共享内存（Unified Buffer）","slug":"共享内存unified-buffer"},{"level":2,"title":"寄存器","slug":"寄存器"}],"relativePath":"guide/编程指南/编程模型/AI-Core-SIMT编程/内存层级.md","filePath":"guide/编程指南/编程模型/AI-Core-SIMT编程/内存层级.md"}'),p={name:"guide/编程指南/编程模型/AI-Core-SIMT编程/内存层级.md"};function i(g,t,r,d,n,q){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="内存层级" tabindex="-1">内存层级 <a class="header-anchor" href="#内存层级" aria-label="Permalink to &quot;内存层级&quot;">​</a></h1><p>SIMT线程可访问多种内存空间。下表汇总了SIMT编程中常见内存类型的作用域及其生命周期。</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.018598140185981%&quot;&gt;&lt;p&gt;内存类型&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.238376162383762%&quot;&gt;&lt;p&gt;线程作用域&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.928207179282072%&quot;&gt;&lt;p&gt;生命周期&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.814818518148186%&quot;&gt;&lt;p&gt;物理位置&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.018598140185981%&quot;&gt;&lt;p&gt;全局内存&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.238376162383762%&quot;&gt;&lt;p&gt;Grid&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.928207179282072%&quot;&gt;&lt;p&gt;应用程序&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.814818518148186%&quot;&gt;&lt;p&gt;Device&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.018598140185981%&quot;&gt;&lt;p&gt;共享内存&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.238376162383762%&quot;&gt;&lt;p&gt;Block&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.928207179282072%&quot;&gt;&lt;p&gt;核函数&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.814818518148186%&quot;&gt;&lt;p&gt;Vector Core&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.018598140185981%&quot;&gt;&lt;p&gt;栈&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.238376162383762%&quot;&gt;&lt;p&gt;Thread&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.928207179282072%&quot;&gt;&lt;p&gt;核函数&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.814818518148186%&quot;&gt;&lt;p&gt;Device&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.018598140185981%&quot;&gt;&lt;p&gt;寄存器&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.238376162383762%&quot;&gt;&lt;p&gt;Thread&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.928207179282072%&quot;&gt;&lt;p&gt;核函数&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.814818518148186%&quot;&gt;&lt;p&gt;Vector Core&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><ul><li>全局内存是所有线程均可直接访问的内存资源，即Global Memory；</li><li>共享内存是线程块内所有线程共享的内存，即Unified Buffer，生命周期和线程块一致。</li><li>每个线程独立的寄存器和栈，用于存储局部变量。</li></ul><p>内存层级如下图所示。</p><p><img src="'+u+`" alt=""></p><h2 id="全局内存-global-memory" tabindex="-1">全局内存（Global Memory） <a class="header-anchor" href="#全局内存-global-memory" aria-label="Permalink to &quot;全局内存（Global Memory）&quot;">​</a></h2><p>Device侧的全局内存是整个Grid中所有线程均可访问的内存空间，其作用与CPU系统中的随机存取存储器（RAM）相似，运行在Device侧的核函数可直接访问全局内存，这种方式与CPU上代码访问系统内存的方式相同。</p><p>全局内存具有持久性：通过全局内存分配的空间、其中存储的数据将持续保留，直到该内存空间被释放或应用程序终止。用户通过Runtime API完成Device侧全局内存的管理。Host使用aclrtMalloc分配Device侧的全局内存，并通过aclrtMemcpy将数据从Host拷贝到Device侧的全局内存，或将数据从Device的全局内存拷贝回Host内存；通过aclrtMalloc分配的Device全局内存需使用aclrtFree接口释放。有关Runtime API的更多信息与细节，可以参考<a href="https://hiascend.com/document/redirect/CannCommunityRuntimeApi" target="_blank" rel="noreferrer">《Runtime运行时API》</a>。</p><p>在实际开发过程中，用户需在核函数启动前，通过Runtime API完成全局内存的分配与初始化；在核函数执行期间，SIMT每个线程均可读取和写入数据到全局内存；核函数执行完毕后，其写入全局内存的结果可拷贝回Host。由于全局内存对Grid内所有线程均开放访问，因此必须严格规避线程间的数据竞争。</p><p>下述代码为全局内存的使用提供了简易示例。数组 x、y、z 均存储于全局内存中，通过以下核函数实现每个线程对全局内存的访问和存储。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__global__ void add_custom(float* x, float* y, float* z, uint64_t total_length)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Calculate global thread ID</span></span>
<span class="line"><span>    int32_t idx = blockIdx.x * blockDim.x + threadIdx.x;</span></span>
<span class="line"><span>    // Maps to the row index of output tensor</span></span>
<span class="line"><span>    if (idx &gt;= total_length) {</span></span>
<span class="line"><span>        return;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    z[idx] = x[idx] + y[idx];</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="共享内存-unified-buffer" tabindex="-1">共享内存（Unified Buffer） <a class="header-anchor" href="#共享内存-unified-buffer" aria-label="Permalink to &quot;共享内存（Unified Buffer）&quot;">​</a></h2><p>共享内存是同一线程块内所有线程均可访问的内存空间，位于每个Vector Core（AIV）内部。与全局内存相比，共享内存的容量较小，但具有更高的带宽和更低的访问延迟，可视为内核执行期间由用户管理的高速缓存资源。由于共享内存可被线程块内的全部线程访问，因此需要注意避免同一线程块内线程间的数据竞争。通过使用asc_syncthreads接口，可以实现同一线程块内的线程同步，该函数会阻塞线程块内的所有线程，直至所有线程均执行到接口调用位置。</p><p>用户可通过动态或者静态方式申请共享内存。</p><ol><li><p>静态申请：分配一段指定大小的内存空间，其大小在编译时确定，不可动态修改，开发者通过数组分配申请使用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__ubuf__ half staticBuf[1024];</span></span></code></pre></div></li><li><p>动态申请：用户需要通过&lt;&lt;&lt;&gt;&gt;&gt;中参数<a href="./核函数.html#li12421238101815">dynUBufSize</a>指定动态内存的空间大小，其大小在运行期确定，SIMT编程中可通过以下方式申请使用动态内存。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extern __ubuf__ char dynamicBuf[];</span></span></code></pre></div></li></ol><p>由于Unified Buffer不仅作为共享内存，还有部分内存空间预留作内部使用，因此用户在申请共享内存时，应注意不能将所有共享内存用尽。如下图，Unified Buffer内存空间总大小为256KB，按功能划分为四个主要区域，从低地址到高地址依次为静态内存、动态内存、预留空间和Data Cache。</p><p><img src="`+s+'" alt=""></p><p>具体结构如下：</p><ol><li>静态内存和动态内存对应用户静态、动态申请方式分配的内存。</li><li>预留空间：编译器和Ascend C预留空间，大小固定为8KB。</li><li>Data Cache：SIMT专有的Data Cache空间，用于SIMT线程访问全局内存时的数据缓存，DataCache的空间可配置范围为32KB到128KB，实际内存大小受用户配置的静态和动态内存大小影响，具体计算公式为：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DataCache空间大小 = UB大小（256KB） - 静态内存 - 动态内存 - 预留空间（8KB）</span></span></code></pre></div>若DataCache小于32KB，会出现校验报错，用户需要合理配置静态和动态内存大小。</li></ol><h2 id="寄存器" tabindex="-1">寄存器 <a class="header-anchor" href="#寄存器" aria-label="Permalink to &quot;寄存器&quot;">​</a></h2><p>SIMT编程中，每个线程拥有独立的寄存器，其生命周期与核函数一致。寄存器的使用由编译器管理，并在核函数执行期间用于线程的局部存储。线程执行时可用寄存器数量与用户配置的<a href="./../../语言扩展层/SIMT-BuiltIn关键字.html#li076017381191">blockDim</a>有关，详见下表。</p><p><strong>表 1</strong> LAUNCH_BOUND的Thread数量与每个Thread可用寄存器数</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.230000000000004%&quot;&gt;&lt;p&gt;&lt;span&gt;blockDim大小&lt;/span&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.77%&quot;&gt;&lt;p&gt;每个Thread可用寄存器个数(个)&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.230000000000004%&quot;&gt;&lt;p&gt;1025~2048&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.77%&quot;&gt;&lt;p&gt;16&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.230000000000004%&quot;&gt;&lt;p&gt;513~1024&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.77%&quot;&gt;&lt;p&gt;32&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.230000000000004%&quot;&gt;&lt;p&gt;257~512&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.77%&quot;&gt;&lt;p&gt;64&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;49.230000000000004%&quot;&gt;&lt;p&gt;1~256&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.77%&quot;&gt;&lt;p&gt;127&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>从上表可知，每个线程块中的线程数量越多，每个线程可使用的寄存器数量就越少。如果用户设置的线程数量过大，而每个线程的计算复杂度又较高时，编译器由于缺乏足够的寄存器来存储本地变量，可能会将数据临时存放到堆栈空间，从而极易导致寄存器溢出（stack spill），影响算子性能。因此，用户应根据实际的算子复杂度，合理配置blockDim。</p>',25)])])}const b=l(p,[["render",i]]);export{h as __pageData,b as default};
